template:
% 参数由系统自动注入：\def\waist{5} \def\base{6} \def\showheight{0}
% 视觉归一化：把底边长缩放到 6（单位由 coordScale 决定），保证图形视觉大小稳定；
% 只缩放坐标，线宽、字体、虚线样式保持不变。
\pgfmathsetmacro{\figscale}{6 / \base}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \pgfmathsetmacro{\half}{\base/2}
  \pgfmathsetmacro{\h}{sqrt(\waist*\waist - \half*\half)}
  \coordinate (B) at (-\half,0);
  \coordinate (C) at (\half,0);
  \coordinate (A) at (0,\h);
  \draw[thick] (A) -- (B) -- (C) -- cycle;
  % 底边上的高（三线合一）：垂足 D 为 BC 中点，虚线
  \ifnum\showheight>0
    \coordinate (D) at (0,0);
    \draw[dashed] (A) -- (D);
    % 垂足处直角记号（朝高线左侧）
    \pgfmathsetmacro\rm{min(0.25, \h*0.2)}
    \draw[thick] (0,\rm) -- (-\rm,\rm) -- (-\rm,0);
    \node[below=3pt] at (D) {$D$};
  \fi
  % 顶点标签放边外侧：A 上、B 左下、C 右下
  \node[above=3pt] at (A) {$A$};
  \node[below left=3pt] at (B) {$B$};
  \node[below right=3pt] at (C) {$C$};
\end{tikzpicture}
